const input = $json.body || $json;

const planId = String(input['Plan ID'] || input.plan_id || '').trim();
const email = String(input['Email Address'] || input.email || '').trim();
const lifeEvent = String(input['Life Event'] || input.life_event || '').trim();
const event = lifeEvent.toLowerCase();

const mapping = {
  'new job': ['emergency_fund', 'savings_goals', 'retirement', 'insurance'],
  'marriage': ['emergency_fund', 'insurance', 'savings_goals', 'retirement'],
  'new child': ['emergency_fund', 'insurance', 'education_savings', 'savings_goals'],
  'home purchase': ['emergency_fund', 'home_purchase', 'debt_strategy', 'savings_goals'],
  'divorce': ['emergency_fund', 'insurance', 'savings_goals', 'retirement', 'debt_strategy'],
  'major income change': ['emergency_fund', 'savings_goals', 'retirement', 'insurance'],
  'major debt': ['emergency_fund', 'debt_strategy', 'savings_goals'],
  'other': ['emergency_fund', 'savings_goals', 'insurance'],
  'no major change': []
};

const affectedSections = mapping[event] || mapping['other'];

return [{
  json: {
    plan_id: planId,
    email: email,
    life_event: lifeEvent,
    event_date: String(input['Event Date'] || input.event_date || ''),
    monthly_income: input['Approximate Monthly Income'] || input.monthly_income || null,
    monthly_expenses: input['Approximate Monthly Expenses'] || input.monthly_expenses || null,
    additional_details: String(input['Additional Details'] || input.additional_details || ''),
    affected_sections: affectedSections,
    affected_section_count: affectedSections.length,
    run_id: 'RUN-' + Date.now()
  }
}];

const trigger = $('Map Event to Plan Sections').first().json;

const planRows = $input.all().map(item => item.json);
const affected = new Set(trigger.affected_sections || []);

const currentPlan = planRows
  .filter(row => String(row.plan_id) === String(trigger.plan_id) && affected.has(String(row.section_key)))
  .map(row => ({
    section_key: String(row.section_key),
    section_name: String(row.section_name || ''),
    current_value: String(row.current_value || ''),
    recommendation: String(row.recommendation || ''),
    priority: String(row.priority || 'medium'),
    version: Number(row.version || 1)
  }));

return [{
  json: {
    plan_id: trigger.plan_id,
    email: trigger.email,
    life_event: trigger.life_event,
    event_date: trigger.event_date,
    monthly_income: trigger.monthly_income,
    monthly_expenses: trigger.monthly_expenses,
    additional_details: trigger.additional_details,
    affected_sections: trigger.affected_sections,
    run_id: trigger.run_id,
    current_plan: currentPlan
  }
}];

const raw = String($json.ai_response_text || '').trim();

let parsed;

try {
  parsed = JSON.parse(raw);
} catch (error) {
  const cleaned = raw
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  try {
    parsed = JSON.parse(cleaned);
  } catch (secondError) {
    return [{
      json: {
        ...$json,
        sections: [],
        overall_summary: '',
        additional_information_needed: [],
        validation_status: 'invalid',
        validation_errors: ['OpenAI response is not valid JSON']
      }
    }];
  }
}

const source = $('Build Plan Refresh Context').first().json;
const allowed = new Set(source.affected_sections || []);
const sections = Array.isArray(parsed.sections) ? parsed.sections : [];
const errors = [];

if (!parsed.plan_id || String(parsed.plan_id) !== String(source.plan_id)) {
  errors.push('Plan ID mismatch');
}

if (sections.length === 0) {
  errors.push('No plan sections returned');
}

for (const section of sections) {
  if (!allowed.has(section.section_key)) {
    errors.push('Returned section is not affected by the reported event: ' + String(section.section_key || ''));
  }

  const confidence = Number(section.confidence);
  if (!Number.isFinite(confidence) || confidence < 0 || confidence > 1) {
    errors.push('Invalid confidence for section: ' + String(section.section_key || ''));
  }

  if (!section.updated_value || !section.updated_recommendation) {
    errors.push('Missing recommendation fields for section: ' + String(section.section_key || ''));
  }
}

return [{
  json: {
    plan_id: source.plan_id,
    email: source.email,
    life_event: source.life_event,
    event_date: source.event_date,
    run_id: source.run_id,
    current_plan: source.current_plan,
    affected_sections: source.affected_sections,
    sections: sections,
    overall_summary: String(parsed.overall_summary || ''),
    additional_information_needed: Array.isArray(parsed.additional_information_needed)
      ? parsed.additional_information_needed
      : [],
    validation_status: errors.length === 0 ? 'valid' : 'invalid',
    validation_errors: errors
  }
}];

const validated = $('Validate Plan AI Output').first().json;
const currentPlan = Array.isArray(validated.current_plan) ? validated.current_plan : [];
const section = $json;

const previous = currentPlan.find(item => item.section_key === section.section_key) || {};
const previousVersion = Number(previous.version || 1);
const nextVersion = previousVersion + 1;

return [{
  json: {
    plan_id: validated.plan_id,
    section_key: String(section.section_key || ''),
    section_name: String(section.section_name || previous.section_name || ''),
    current_value: String(section.updated_value || ''),
    recommendation: String(section.updated_recommendation || ''),
    priority: String(section.priority || previous.priority || 'medium'),
    status: 'active',
    last_updated: new Date().toISOString(),
    source_event: validated.life_event,
    version: String(nextVersion),
    history_id: 'HIST-' + Date.now() + '-' + $itemIndex,
    previous_value: String(previous.current_value || ''),
    previous_recommendation: String(previous.recommendation || ''),
    new_value: String(section.updated_value || ''),
    new_recommendation: String(section.updated_recommendation || ''),
    change_reason: validated.life_event,
    event_date: validated.event_date,
    changed_at: new Date().toISOString()
  }
}];

